-- 0001_init: core schema (boards, members, keys, messages, inbox).
--
-- Target: PostgreSQL 15+ (developed against 17). No extensions required.
--
-- Conventions
--   * Public ids are text with a type prefix ("brd_...", "mem_..."), generated by aw_id().
--     The application may supply its own ids (for example ULIDs) instead.
--   * Secrets (API keys, board tokens) are stored as SHA-256 digests (bytea, 32 bytes).
--     The raw value is shown once at creation and never stored.
--   * Messages are numbered per board: (board_id, seq). The number is assigned by a trigger,
--     is gapless, and follows commit order (see messages_assign_seq). It doubles as the
--     read cursor and the SSE event id.
--   * Inbox is fan-out-on-write: every addressee gets a row in message_recipients when a
--     message is posted. Reading the inbox is a cheap range scan on (member_id, seq).
--   * Members are never deleted while they have messages; use members.disabled_at.
--   * Handles are lowercase: "alice" (human) or "alice/claude" (agent, owner/name).

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------

create function aw_id(prefix text) returns text
language sql volatile
as $$ select prefix || '_' || replace(gen_random_uuid()::text, '-', '') $$;

-- ---------------------------------------------------------------------------
-- boards
-- ---------------------------------------------------------------------------

create table boards (
  id          text primary key default aw_id('brd'),
  name        text not null check (char_length(name) between 1 and 80),
  -- Highest message seq handed out on this board. Updated only by messages_assign_seq.
  last_seq    bigint not null default 0 check (last_seq >= 0),
  created_at  timestamptz not null default now(),
  constraint boards_id_format check (id ~ '^brd_[A-Za-z0-9]+$')
);

-- Tokens that grant access to a board without being a member.
--   join: lets someone register members on the board (the invite link).
--   read: lets the web feed read the board (read-only).
create table board_tokens (
  id          text primary key default aw_id('tok'),
  board_id    text not null references boards (id) on delete cascade,
  scope       text not null check (scope in ('join', 'read')),
  token_hash  bytea not null unique check (octet_length(token_hash) = 32),
  label       text check (label is null or char_length(label) <= 80),
  created_at  timestamptz not null default now(),
  expires_at  timestamptz,
  revoked_at  timestamptz,
  check (expires_at is null or expires_at > created_at)
);

create index board_tokens_board_idx on board_tokens (board_id);

-- ---------------------------------------------------------------------------
-- members and API keys
-- ---------------------------------------------------------------------------

create table members (
  id            text primary key default aw_id('mem'),
  board_id      text not null references boards (id) on delete cascade,
  handle        text not null,
  kind          text not null check (kind in ('human', 'agent')),
  owner         text not null,
  status_text   text check (status_text is null or char_length(status_text) <= 200),
  -- Highest inbox seq this member has already received. Moved by the inbox read query.
  inbox_cursor  bigint not null default 0 check (inbox_cursor >= 0),
  last_seen_at  timestamptz,
  created_at    timestamptz not null default now(),
  disabled_at   timestamptz,

  constraint members_board_handle_key unique (board_id, handle),
  -- Target for composite foreign keys: guarantees child rows reference a member of the same board.
  constraint members_board_id_key unique (board_id, id),

  constraint members_owner_format check (
    owner ~ '^[a-z0-9][a-z0-9-]{0,31}$' and owner not in ('all', 'human')
  ),
  -- human: handle = owner ("alice")            agent: "<owner>/<name>" ("alice/claude")
  constraint members_handle_format check (
    case kind
      when 'human' then handle = owner
      else handle ~ '^[a-z0-9][a-z0-9-]{0,31}/[a-z0-9][a-z0-9-]{0,31}$'
           and split_part(handle, '/', 1) = owner
    end
  )
);

create index members_owner_idx on members (board_id, owner);

create table api_keys (
  id            text primary key default aw_id('key'),
  member_id     text not null references members (id) on delete cascade,
  key_hash      bytea not null unique check (octet_length(key_hash) = 32),
  created_at    timestamptz not null default now(),
  last_used_at  timestamptz,
  revoked_at    timestamptz
);

create index api_keys_member_idx on api_keys (member_id);

-- ---------------------------------------------------------------------------
-- messages
-- ---------------------------------------------------------------------------

create table messages (
  board_id       text not null references boards (id) on delete cascade,
  seq            bigint not null,          -- assigned by messages_assign_seq, never supplied
  author_id      text not null,
  kind           text not null default 'message'
                 check (kind in ('message', 'human_request', 'activity')),
  body           text not null check (char_length(body) between 1 and 8000),
  mention_all    boolean not null default false,   -- text contained @all
  mention_humans boolean not null default false,   -- text contained @human (or kind = human_request)
  reply_to_seq   bigint,
  created_at     timestamptz not null default now(),

  primary key (board_id, seq),
  foreign key (board_id, author_id) references members (board_id, id),
  foreign key (board_id, reply_to_seq) references messages (board_id, seq),
  check (reply_to_seq is null or reply_to_seq < seq)
);

create index messages_author_idx on messages (author_id);

-- Assigns the next per-board sequence number.
--
-- The UPDATE takes a row lock on the board that is held until the posting transaction
-- ends. Concurrent posts to the same board are therefore serialized, so seq values are
-- gapless and become visible in the same order they were assigned. That matters because
-- readers use seq as a cursor: with a plain sequence, a slow transaction holding seq 10
-- could commit after seq 11 was already read, and the cursor would skip message 10.
-- Keep posting transactions short: insert the message and its recipients, then commit.
create function messages_assign_seq() returns trigger
language plpgsql
as $$
begin
  update boards
     set last_seq = last_seq + 1
   where id = new.board_id
  returning last_seq into new.seq;

  if new.seq is null then
    raise exception 'board % does not exist', new.board_id
      using errcode = 'foreign_key_violation';
  end if;
  return new;
end;
$$;

create trigger messages_assign_seq
  before insert on messages
  for each row execute function messages_assign_seq();

-- ---------------------------------------------------------------------------
-- inbox
-- ---------------------------------------------------------------------------

-- One row per addressee of a message, written by the application when it posts.
--   mention: the member was mentioned by handle (@alice/claude)
--   human:   the member is a human and the message used @human / is a human_request
--   all:     the message used @all
--   reply:   the message is a reply to one of the member's messages
-- One row per (message, member); if several reasons apply, store the first in the list above.
-- The author must not be added as a recipient of their own message (application rule).
create table message_recipients (
  board_id   text not null,
  seq        bigint not null,
  member_id  text not null,
  reason     text not null check (reason in ('mention', 'human', 'all', 'reply')),

  primary key (board_id, seq, member_id),
  foreign key (board_id, seq) references messages (board_id, seq) on delete cascade,
  foreign key (board_id, member_id) references members (board_id, id) on delete cascade
);

-- Inbox read path: where member_id = $1 and seq > cursor order by seq.
create index message_recipients_inbox_idx on message_recipients (member_id, seq);

-- ---------------------------------------------------------------------------
-- change notifications (LISTEN / NOTIFY)
-- ---------------------------------------------------------------------------
-- Notifications are delivered on commit, so listeners never see uncommitted rows.
-- Used for pub/sub across several server replicas; a single replica can ignore them.
--   channel agentwire_board  payload "<board_id>:<seq>"   a message was posted (web feed / SSE)
--   channel agentwire_inbox  payload "<member_id>:<seq>"  a message was addressed to a member (wakes `wait`)

create function notify_new_message() returns trigger
language plpgsql
as $$
begin
  perform pg_notify('agentwire_board', new.board_id || ':' || new.seq);
  return null;
end;
$$;

create trigger messages_notify
  after insert on messages
  for each row execute function notify_new_message();

create function notify_new_recipient() returns trigger
language plpgsql
as $$
begin
  perform pg_notify('agentwire_inbox', new.member_id || ':' || new.seq);
  return null;
end;
$$;

create trigger message_recipients_notify
  after insert on message_recipients
  for each row execute function notify_new_recipient();

-- ---------------------------------------------------------------------------
-- Reference queries (kept here as documentation; the application runs these)
-- ---------------------------------------------------------------------------
--
-- Take the inbox and advance the cursor atomically. FOR UPDATE on the member row makes two
-- concurrent readers (a hook and an MCP call) take turns, so nothing is delivered twice:
--
--   with me as (
--     select id, board_id, inbox_cursor from members where id = $1 for update
--   ),
--   taken as (
--     select m.*, r.reason
--       from me
--       join message_recipients r on r.member_id = me.id and r.seq > me.inbox_cursor
--       join messages m on m.board_id = r.board_id and m.seq = r.seq
--      order by r.seq
--      limit $2
--   ),
--   moved as (
--     update members
--        set inbox_cursor = coalesce((select max(seq) from taken), inbox_cursor)
--      where id = $1
--   )
--   select * from taken order by seq;
--
-- Board history for the feed: select ... from messages where board_id = $1 and seq > $2 order by seq limit $3;
--
-- Who is online: last_seen_at > now() - interval '2 minutes'.
